import subprocess, signal, time, os
for sig,name in [(signal.SIGINT,"INT"),(signal.SIGTERM,"TERM"),(signal.SIGQUIT,"QUIT"),(signal.SIGHUP,"HUP")]:
    p=subprocess.Popen(["./executable","-m","cargo","-s","1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
