import subprocess, time, select, os
def timed(args, dur=4):
    p=subprocess.Popen(["./executable"]+args, stdout=subprocess.PIPE)
    start=time.time(); buf=b""; times=[]
    while time.time()-start<dur:
        r,_,_=select.select([p.stdout],[],[],0.05)
        if r:
            chunk=os.read(p.stdout.fileno(), 4096)
            if not chunk: break
            buf+=chunk
            while b"\n" in buf:
                line,buf=buf.split(b"\n",1)
                times.append(time.time()-start)
        if p.poll() is not None: break
    p.kill()
    return times
for i in [0,1,2,3,10]:
    for trial in range(2):
        t=timed(["-m","cargo","-i",str(i)])
        print("i",i, [round(x,3) for x in t[:15]])
PY"}

