import subprocess, time, select, os, signal
def test(args, sig_at=1.0):
    p=subprocess.Popen(["./executable"]+args, stdout=subprocess.PIPE)
    start=time.time(); buf=b""
    sent=False
    while True:
        elapsed=time.time()-start
        if not sent and elapsed>=sig_at:
            p.send_signal(signal.SIGINT); sent=True; print(f"{elapsed:.3f} sent SIGINT")
        r,_,_=select.select([p.stdout],[],[],0.05)
        if r:
            chunk=os.read(p.stdout.fileno(), 4096)
            if not chunk: break
            buf+=chunk
            while b"\n" in buf:
                line,buf=buf.split(b"\n",1)
                print(f"{time.time()-start:.3f}", line[:80])
        if p.poll() is not None:
            print("exit", time.time()-start, p.returncode); break
        if elapsed>8:
            p.kill(); print("kill"); break
test(["-m","cargo"])
print("--- term")
test(["-m","cargo"], )
