import subprocess, re, os, collections, sys, time
outdir="/tmp/extract"
def run(mod, n=8, timeout=10):
    txts=[]
    for i in range(n):
        try:
            r=subprocess.run(["./executable","-m",mod,"-s","inf","--exit-after-modules","1"], capture_output=True, timeout=timeout)
            txts.append(r.stdout.decode(errors='replace'))
        except subprocess.TimeoutExpired as e:
            txts.append((e.stdout or b"").decode(errors='replace'))
    return txts

def save(name, items):
    items=sorted(set(items))
    open(os.path.join(outdir,name),"w").write("\n".join(items)+"\n")
    print(name, len(items))

# bootlog
lines=[]
for t in run("bootlog", 20):
    for l in t.split("\r\n"):
        lines.append(l)
save("bootlog_raw.txt", lines)

# cargo names
names=[]
for t in run("cargo", 6):
    names+=re.findall(r'Downloading\x1b\[0m (\S+) v', t)
save("crate_names.txt", names)

# composer
cnames=[]
for t in run("composer", 6):
    cnames+=re.findall(r'Installing \x1b\[32m([^\x1b]+)\x1b', t)
save("composer_names.txt", cnames)

# terraform
rtypes=[]; rnames=[]
for t in run("terraform", 6):
    for m in re.finditer(r'\x1b\[1m(\S+)\.(\w+):', t):
        rtypes.append(m.group(1)); rnames.append(m.group(2))
save("terraform_types.txt", rtypes); save("terraform_names.txt", rnames)

# docker_image_rm
imgs=[]
for t in run("docker_image_rm", 4):
    imgs+=re.findall(r'Untagged: ([^\r\n@]+)(?:\r|$)', t)
    # only first of pair - those without @ - actually regex captures without @, both lines will duplicate
save("docker_images.txt", imgs)

# weblog
uas=[]; exts=[]; words=[]
for t in run("weblog", 4):
    for l in t.split("\r\n"):
        m=re.search(r'" "\s*"([^"]*)"$', l) or re.search(r'"-" "([^"]*)"', l)
        if m: uas.append(m.group(1))
        m2=re.search(r'"GET ([^ ]+) HTTP', l)
        if m2:
            segs=m2.group(1).strip("/").split("/")
            for s in segs[:-1]: words.append(s)
            if segs:
                last=segs[-1]
                if "." in last: exts.append(last.rsplit(".",1)[-1])
save("weblog_uas.txt", uas); save("weblog_exts.txt", exts); save("weblog_path_words.txt", words)

# wpt paths categories
cats=[]
for t in run("wpt", 2, timeout=15):
    for p in re.findall(r'(/[^\s]+/test-)\d+\.html', t):
        cats.append(p)
save("wpt_cats.txt", cats)

# kernel/cc paths
kpaths=[]
for t in run("kernel_compile", 5):
    for l in t.split("\r\n"):
        parts=l.strip().split()
        if len(parts)>=2:
            kpaths.append(parts[-1])
save("kernel_paths.txt", kpaths)

cpaths=[]
for t in run("cc", 3):
    for l in t.split("\r\n"):
        m=re.search(r' -o (\S+)', l)
        if m: cpaths.append(m.group(1))
save("cc_objects.txt", cpaths)

# memdump etc no

# julia package names
jnames=[]
for t in run("julia", 4):
    jnames+=re.findall(r'Installed\x1b\[0m (\S+)', t)
    jnames+=re.findall(r'artifact: (\S+)', t)
save("julia_names.txt", jnames)

# rkhunter
rlines=[]
for t in run("rkhunter", 8):
    for l in t.split("\r\n"):
        rlines.append(l)
save("rkhunter_lines.txt", rlines)

# mkinitcpio hooks/versions/compression
hooks=[]; vers=[]; comps=[]
for t in run("mkinitcpio", 8):
    hooks+=re.findall(r'Running build hook: \[([^\]]+)\]', t)
    vers+=re.findall(r'Starting build: (\S+)', t)
    comps+=re.findall(r'Creating (\S+)-compressed', t)
save("mk_hooks.txt", hooks); save("mk_versions.txt", vers); save("mk_comps.txt", comps)

print("done")
PY
