import subprocess, time, select, os
def measure(mod, dur=5, speed="10"):
    p=subprocess.Popen(["./executable","-m",mod,"-s",speed], stdout=subprocess.PIPE)
    start=time.time(); buf=b""; times=[]
    while time.time()-start<dur:
        r,_,_=select.select([p.stdout],[],[],0.05)
        if r:
            chunk=os.read(p.stdout.fileno(), 65536)
            if not chunk: break
            buf+=chunk
            while b"\n" in buf:
                line,buf=buf.split(b"\n",1); times.append(time.time()-start)
        if p.poll() is not None: break
    p.kill()
    diffs=[round(b-a,3) for a,b in zip(times, times[1:])]
    print(mod, "lines in", dur, len(times), "intervals first20", diffs[:20])
for m in ["bootlog","cargo","composer","mkinitcpio","memdump","kernel_compile","terraform","weblog","cc","docker_image_rm"]:
    measure(m)
