//! Minimal terminal size query compatible with the API used by clap_builder.
//! On Unix this issues TIOCGWINSZ ioctls against stdout, stderr and stdin,
//! in that order, skipping descriptors that report a zero-sized dimension.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

