use std::io::Write;
use std::os::unix::io::FromRawFd;
use std::sync::atomic::{AtomicBool, AtomicU32, AtomicU64, Ordering};
use std::sync::Mutex;
use std::time::{Duration, Instant};

pub static SPEED_FACTOR: AtomicU64 = AtomicU64::new(0x3ff0_0000_0000_0000);
pub static INSTANT_LINES: AtomicU32 = AtomicU32::new(0);
pub static SHOULD_EXIT: AtomicBool = AtomicBool::new(false);
pub static DEADLINE: Mutex<Option<Instant>> = Mutex::new(None);

pub fn init(speed_factor: f64, instant_print_lines: u32, exit_after: Option<Duration>) {
    SPEED_FACTOR.store(speed_factor.to_bits(), Ordering::Relaxed);
    INSTANT_LINES.store(instant_print_lines, Ordering::Relaxed);
    if let Some(duration) = exit_after {
        let mut guard = DEADLINE.lock().unwrap();
        *guard = Some(Instant::now() + duration);
    }
}

pub fn speed_factor() -> f64 {
    f64::from_bits(SPEED_FACTOR.load(Ordering::Relaxed))
}

pub fn exit_requested() -> bool {
    if SHOULD_EXIT.load(Ordering::Relaxed) {
        return true;
    }
    let deadline = *DEADLINE.lock().unwrap();
    if let Some(deadline) = deadline {
        if Instant::now() >= deadline {
            SHOULD_EXIT.store(true, Ordering::Relaxed);
            return true;
        }
    }
    false
}

pub fn sleep_scaled(base_millis: u64) {
    if base_millis == 0 {
        return;
    }
    let scaled = (base_millis as f64) / speed_factor();
    if scaled.is_nan() || scaled <= 0.0 {
        return;
    }
    let total = if scaled > 9.0e18 { u64::MAX } else { scaled as u64 };
    let started = Instant::now();
    loop {
        if exit_requested() {
            return;
        }
        let elapsed = started.elapsed().as_millis() as u64;
        if elapsed >= total {
            return;
        }
        let remaining = total - elapsed;
        std::thread::sleep(Duration::from_millis(remaining.min(5)));
    }
}

fn after_print(base_millis: u64) {
    let remaining = INSTANT_LINES.load(Ordering::Relaxed);
    if remaining > 0 {
        INSTANT_LINES.store(remaining - 1, Ordering::Relaxed);
        return;
    }
    sleep_scaled(base_millis);
}

pub fn print_bootlog_line(content: &str, delay: u64) {
    let mut out = std::mem::ManuallyDrop::new(unsafe { std::fs::File::from_raw_fd(1) });
        out.write_all(content.as_bytes()).unwrap();
    after_print(delay);
}

pub fn print_string(content: &str, delay: u64) {
    print_line_raw(content, delay);
}

pub fn print_line(content: &str, delay: u64) {
    let text = format!("{content}\r\n");
    print_line_raw(&text, delay);
}

fn print_line_raw(content: &str, delay: u64) {
    let mut out = std::mem::ManuallyDrop::new(unsafe { std::fs::File::from_raw_fd(1) });
        out.write_all(content.as_bytes()).unwrap();
    after_print(delay);
}

pub fn get_terminal_width() -> usize {
    if let Some((terminal_size::Width(width), _)) = terminal_size::terminal_size() {
        width as usize
    } else {
        panic!("Couldn't get terminal width. Is an interactive terminal attached?")
    }
}
