use rand::Rng;

pub fn rng() -> rand::rngs::ThreadRng {
    rand::thread_rng()
}

pub fn choose<'a, T>(items: &'a [T]) -> &'a T {
    let mut r = rng();
    &items[r.gen_range(0..items.len())]
}

pub fn choose_str<'a>(items: &'a [&'a str]) -> &'a str {
    choose(items)
}

pub fn range(min: u64, max_inclusive: u64) -> u64 {
    rng().gen_range(min..=max_inclusive)
}

pub fn range_usize(min: usize, max_inclusive: usize) -> usize {
    rng().gen_range(min..=max_inclusive)
}

pub fn chance(percent: u32) -> bool {
    rng().gen_range(0..100) < percent
}

pub fn hex_string(len: usize) -> String {
    const HEX: &[u8] = b"0123456789abcdef";
    let mut r = rng();
    (0..len)
        .map(|_| HEX[r.gen_range(0..16)] as char)
        .collect()
}

pub fn random_bytes(count: usize) -> Vec<u8> {
    let mut r = rng();
    (0..count).map(|_| r.gen::<u8>()).collect()
}

pub fn ipv4() -> String {
    let mut r = rng();
    format!(
        "{}.{}.{}.{}",
        r.gen::<u8>(),
        r.gen::<u8>(),
        r.gen::<u8>(),
        r.gen::<u8>()
    )
}

pub fn ipv6() -> String {
    let mut r = rng();
    (0..8)
        .map(|_| format!("{:x}", r.gen::<u16>()))
        .collect::<Vec<_>>()
        .join(":")
}

pub fn ip() -> String {
    if chance(50) {
        ipv4()
    } else {
        ipv6()
    }
}

pub fn version() -> String {
    let mut r = rng();
    let major = match r.gen_range(0..100) {
        0..=64 => 0,
        65..=89 => 1,
        90..=96 => 2,
        _ => 3,
    };
    let minor = (r.gen::<f64>() * r.gen::<f64>() * 80.0) as u32;
    let patch = (r.gen::<f64>() * r.gen::<f64>() * 60.0) as u32;
    format!("{major}.{minor}.{patch}")
}

pub fn wide_version() -> String {
    let mut r = rng();
    let a = (r.gen::<f64>() * r.gen::<f64>() * 72.0) as u32;
    let b = (r.gen::<f64>() * r.gen::<f64>() * 72.0) as u32;
    let c = (r.gen::<f64>() * r.gen::<f64>() * 72.0) as u32;
    format!("{a}.{b}.{c}")
}

