    if rootkit_section {
        let rootkits = ["beX2", "Dica", "Marvin", "Sneakin", "Suspicion"];
        let rootkit = choose_str(&rootkits);
        say(&format!("  Checking for {rootkit} Rootkit..."));
        let count = range_usize(10, 20);
        let selected: Vec<&str> = items.iter().take(count).cloned().collect();
        let width = selected.iter().map(|s| s.len()).max().unwrap_or(40) + 6;
        for item in &selected {
            if exited() { return; }
            let status = rkhunter_status();
            say(&format!("    {:<width$}{}", item, status, width = width));
            io::sleep_scaled(delay(700));
        }
        say(&format!("  {:<width$}{}", format!("{rootkit} Rootkit"), rkhunter_status(), width = width));
        say("");
    } else {
        let count = range_usize(10, 25);
        let selected: Vec<&str> = items.iter().take(count).cloned().collect();
        let width = selected.iter().map(|s| s.len()).max().unwrap_or(40) + 6;
        for item in &selected {
            if exited() { return; }
            let status = rkhunter_status();
            say(&format!("  {:<width$}{}", item, status, width = width));
            io::sleep_scaled(delay(700));
        }
        say("");
    }
}

fn rkhunter_status() -> String {
    match range(0, 99) {
        0..=84 => "[ Not found\x1b[0m ]".to_string(),
        85..=94 => "[ \x1b[31mFound\x1b[0m ]".to_string(),
        _ => "[ Skipped\x1b[0m ]".to_string(),
    }
}

fn simcity() {
    let phrases = data::lines(data::SIMCITY_PHRASES);
    const SPIN: [char; 4] = ['/', '-', '\\', '|'];
    let mut first = true;
    loop {
        if exited() { return; }
        let phrase = *choose(&phrases);
        let spins = range_usize(30, 90);
        for i in 0..spins {
            if exited() { return; }
            let prefix = if first { "" } else { "\r" };
            first = false;
            ps(&format!("{prefix}[ ] {phrase}... {}", SPIN[i % 4]), 80);
        }
        pl(&format!("\r[o] \x1b[37m{phrase}... OK\x1b[0m"), 80);
        first = false;
    }
}

fn terraform() {
    let start = std::time::Instant::now();
    pl("Acquiring state lock. This may take a few moments...", 300);
    let types = data::lines(data::TERRAFORM_TYPES);
    let names = data::lines(data::TERRAFORM_NAMES);
    let count = range_usize(90, 270);
    for _ in 0..count {
        if exited() { return; }
        let ty = choose(&types);
        let name = choose(&names);
        let elapsed = start.elapsed().as_secs();
        let status = match range(0, 9) {
            0 => "Creating...".to_string(),
            1 => format!("Creation complete after {elapsed}s [id={name}]"),
            2 => format!("Destroying... [id={name}]"),
            3 => format!("Destruction complete after {elapsed}s"),
            4 => format!("Modifying... [id={name}]"),
            5 => format!("Modifications complete after {elapsed}s [id={name}]"),
            6 => format!("Still creating... [{elapsed}s elapsed]"),
            7 => format!("Still modifying... [id={name}, {elapsed}s elapsed]"),
            8 => format!("Still destroying... [id={name}, {elapsed}s elapsed]"),
            _ => format!("Refreshing state... [id={name}]"),
        };
        pl(&format!("\x1b[1m{ty}.{name}: {status}\x1b[0m"), delay(400));
    }
}

fn format_size(mib: f64) -> String {
    if mib < 1.0 {
        format!("{:.2} KiB", mib * 1024.0)
    } else {
        format!("{mib:.2} MiB")
    }
}

fn uv() {
    let minor = range(9, 13);
    pl(&format!("Using CPython 3.{}.{}", minor, range(0, 25)), 100);
    pl("Creating virtualenv at: .venv", 100);
    let pool = data::lines(data::CRATE_NAMES);
    let mut packages: Vec<(String, String)> = Vec::new();
    let mut names = shuffled(pool.clone());
    let count = range_usize(70, 170);
    for i in 0..count {
        let name = names[i % names.len()].to_string();
        packages.push((name, version()));
    }
    const SPINNERS: [&str; 10] = ["⠋","⠙","⠹","⠸","⠼","⠴","⠦","⠧","⠇","⠏"];
    for (i, (name, ver)) in packages.iter().enumerate() {
        if exited() { return; }
        ps(&format!("\x1b[2K\x1b[0G{} {name}=={ver}", SPINNERS[i % 10]), 10);
    }
    let resolved_ms: f64 = rng().gen_range(50.0..300.0);
    ps(&format!("\x1b[2K\x1b[0G\x1b[2mResolved {} packages in {resolved_ms:.2}ms\x1b[0m", packages.len()), 10);
    let prepared = range_usize(50, 100);
    for i in 1..=prepared {
        ps(&format!("\x1b[2K\x1b[0G\x1b[2m{} Preparing packages... ({i}/{prepared})\x1b[0m", SPINNERS[i % 10]), 10);
    }
    let prepared_ms: f64 = rng().gen_range(40.0..200.0);
    ps(&format!("\x1b[2K\x1b[0G\x1b[2mPrepared {prepared} packages in {prepared_ms:.2}ms\x1b[0m"), 10);
    pl("", 0);
    pl("", 0);
    // Download each package with a dash progress bar.
    for (name, _) in &packages {
        if exited() { return; }
        let total: f64 = rng().gen_range(0.5..20.0);
        let steps = range_usize(4, 15);
        for step in 1..=steps {
            let current = total * step as f64 / steps as f64;
            let filled = (30.0 * current / total) as usize;
            let bar = format!("{}{}", "-".repeat(filled), " ".repeat(30 - filled));
            let pair = format!("{}/{}", format_size(current), format_size(total));
            pl(&format!("\x1b[1A\x1b[2K\x1b[0G\x1b[2m{name}\x1b[0m{} \x1b[32m{bar}\x1b[0m{pair:>22}  ", " ".repeat(33usize.saturating_sub(name.len()))), 30);
        }
    }
    // Installing wheels
    for i in 0..=prepared {
        if exited() { return; }
        let filled = if prepared == 0 { 30 } else { 30 * i / prepared };
        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(30 - filled));
        ps(&format!("\x1b[2K\x1b[0G[{bar}] [{i}/{prepared}] Installing wheels..."), 10);
    }
    let secs: f64 = rng().gen_range(0.5..3.0);
    ps(&format!("\x1b[2K\x1b[0G\x1b[2mInstalled {prepared} packages in {secs:.2}s\x1b[0m"), 0);
    pl("", 0);
}

fn weblog() {
    let words = data::lines(data::WEBLOG_PATH_WORDS);
    let exts = data::lines(data::WEBLOG_EXTS);
    let uas = data::lines(data::WEBLOG_UAS);
    let crates = data::lines(data::CRATE_NAMES);
    let statuses = [200, 201, 400, 401, 403, 404, 500, 502, 503];
    let count = range_usize(60, 160);
    for _ in 0..count {
        if exited() { return; }
        let segments = range_usize(1, 5);
        let mut path = String::new();
        for _ in 0..segments {
            path.push('/');
            path.push_str(choose(&words));
        }
        let base = choose(&crates);
        let ext = choose(&exts);
        if ["zstd", "bz2", "gz", "xz", "lz4"].contains(ext) && chance(40) {
            path.push_str(&format!("/{base}.tar.{ext}"));
        } else {
            path.push_str(&format!("/{base}.{ext}"));
        }
        let time = chrono::Utc::now().format("%d/%b/%Y:%H:%M:%S +0000");
        let status = choose(&statuses);
        let size = range(10000, 5000000);
        let ua = choose(&uas);
        pl(&format!("{} - - [{time}] \"GET {path} HTTP/1.0\" {status} {size} \"-\" \"{ua}\"", ip()), delay(900));
    }
}

fn wpt() {
    let cats = data::lines(data::WPT_CATS);
    let total_tests = range(15000, 25000);
    let test_path = |cats: &Vec<&str>| -> String {
        format!("{}{}.html", choose(cats), range(1, 500))
    };
    pl(&format!("Running {total_tests} tests in web-platform-tests"), 100);
    pl(&format!("\x1b[A\x1b[K[0/{total_tests}] No tests running."), 50);
    let mut done: u64 = 0;
    while done < total_tests {
        if exited() { return; }
        // Occasional result blocks
        if chance(35) {
            let file = test_path(&cats);
            let base = file.rsplit('/').next().unwrap_or("test").trim_end_matches(".html");
            if chance(40) {
                pl(&format!("\x1b[A\x1b[K    ▶ Timed out in {file}"), 20);
                let expected = choose_str(&["PASS", "FAIL"]);
                let kind = choose_str(&["TIMEOUT", "FAIL", "PASS"]);
                pl(&format!("    │ ERROR [expected {expected}] {kind} test_{base} assert_"), 20);
            } else {
                pl(&format!("\x1b[A\x1b[K    ▶ Unexpected subtest result in {file}:"), 20);
                let expected = choose_str(&["PASS", "FAIL"]);
                let kind = choose_str(&["FAIL", "PASS", "TIMEOUT"]);
                let msg = match range(0, 3) {
                    0 => format!("assert_equals: expected {} but got {}", range(0, 500), range(0, 500)),
                    1 => "assert_throws_dom: function \"() => test()\" threw object \"TypeError: undefined is not a function\" that is not a DOMException".to_string(),
                    2 => "assert_true: expected true".to_string(),
                    _ => "assert_".to_string(),
                };
                pl(&format!("    │ ERROR [expected {expected}] {kind} test_{base} {msg}"), 20);
                let stack = range_usize(2, 6);
                for s in 0..stack {
                    let last = s + 1 == stack;
                    let marker = if last { "└" } else { "│" };
                    let loc = match range(0, 3) {
                        0 => format!("assert_wrapper (http://web-platform.test:8000/resources/testharness.js:{}:{})", range(1, 3000), range(1, 60)),
                        1 => format!("http://web-platform.test:8000/{file}:{}:{}", range(1, 200), range(1, 100)),
                        2 => "<unknown>".to_string(),
                        _ => format!("test (http://web-platform.test:8000/resources/testharness.js:{}:{})", range(1, 3000), range(1, 60)),
                    };
                    pl(&format!("    {marker}   at {loc}"), 20);
                }
                pl("", 20);
            }
        }
        done = (done + range(0, 25)).min(total_tests + 20);
        let mut running: Vec<String> = (0..range_usize(10, 15)).map(|_| test_path(&cats)).collect();
        running.dedup();
        pl(&format!("\x1b[A\x1b[K[{done}/{total_tests}] {} ", running.join(" ")), 20);
    }
    pl(&format!("\x1b[A\x1b[KRan {}/{total_tests} tests with {} failed subtests of {}.", total_tests + range(0, 20), range(10000, 20000), range(500000, 700000)), 0);
}
