cat > src/modules.rs <<'RS'
use crate::data;
use crate::io;
use crate::utils::*;
use rand::seq::SliceRandom;
use rand::Rng;

fn pl(text: &str, delay: u64) {
    io::print_line(text, delay);
}
fn ps(text: &str, delay: u64) {
    io::print_string(text, delay);
}
fn exited() -> bool {
    io::exit_requested()
}
fn delay(range_max: u64) -> u64 {
    if range_max == 0 { 0 } else { rng().gen_range(0..=range_max) }
}
fn shuffled(mut items: Vec<&str>) -> Vec<&str> {
    items.shuffle(&mut rng());
    items
}

pub fn run(module: &str) {
    match module {
        "ansible" => ansible(),
        "bootlog" => bootlog(),
        "botnet" => botnet(),
        "bruteforce" => bruteforce(),
        "cargo" => cargo(),
        "cc" => cc(),
        "composer" => composer(),
        "cryptomining" => cryptomining(),
        "docker_build" => docker_build(),
        "docker_image_rm" => docker_image_rm(),
        "download" => download(),
        "julia" => julia(),
        "kernel_compile" => kernel_compile(),
        "memdump" => memdump(),
        "mkinitcpio" => mkinitcpio(),
        "rkhunter" => rkhunter(),
        "simcity" => simcity(),
        "terraform" => terraform(),
        "uv" => uv(),
        "weblog" => weblog(),
        "wpt" => wpt(),
        _ => {}
    }
}

fn ansible() {
    let width = io::get_terminal_width();
    let latin = data::lines(data::WEBLOG_PATH_WORDS);
    let roles = data::lines(data::ANSIBLE_ROLES);
    let tasks = data::lines(data::ANSIBLE_TASKS);
    let play = format!("{}_{}", first_name(), choose(&latin));
    let play_line = format!("PLAY [setup {play}]");
    let padded = if play_line.len() >= width {
        play_line.clone()
    } else {
        format!("{}{}", play_line, "*".repeat(width - play_line.len()))
    };
    pl(&padded, 200);
    pl("", 0);
    let host_count = range_usize(15, 30);
    let hosts: Vec<String> = (0..host_count).map(|_| ip()).collect();
    let total_tasks = range_usize(15, 30);
    let mut task_index = 0usize;
    while task_index < total_tasks {
        if exited() { return; }
        let (task_name, gathering) = if task_index == 0 {
            ("Gathering Facts".to_string(), true)
        } else {
            // Tasks arrive in small groups that share a role.
            let group = range_usize(1, 5);
            let role = choose(&roles);
            for _ in 0..group {
                if task_index >= total_tasks || exited() { break; }
                let name = format!("{} : {}", role, choose(&tasks));
                print_task(&name, width, &hosts, false);
                task_index += 1;
            }
            continue;
        };
        print_task(&task_name, width, &hosts, gathering);
        task_index += 1;
    }
}

fn print_task(name: &str, width: usize, hosts: &[String], gathering: bool) {
    let header = format!("TASK [{name}]");
    let padded = if header.len() >= width {
        header.clone()
    } else {
        format!("{}{}", header, "*".repeat(width - header.len()))
    };
    ps(&padded, 100);
    for host in hosts {
        if exited() { return; }
        let (status, code) = if gathering {
            ("ok", 32)
        } else {
            match range(0, 99) {
                0..=74 => ("ok", 32),
                75..=92 => ("changed", 33),
                93..=97 => ("failed", 31),
                _ => ("skipping", 36),
            }
        };
        pl(&format!("\x1b[{code}m{status}: [{host}]\x1b[0m"), delay(300));
    }
    pl("", 0);
}

fn bootlog() {
    let pool = data::lines(data::BOOTLOG);
    let count = range_usize(50, 180);
    for _ in 0..count {
        if exited() { return; }
        let line = *choose(&pool);
        let styled = if chance(1) {
            format!("\x1b[31mERROR: {line}\x1b[0m")
        } else if chance(9) {
            match line.find(' ') {
                Some(idx) => format!("\x1b[1m{}\x1b[0m{}", &line[..idx], &line[idx..]),
                None => format!("\x1b[1m{line}\x1b[0m"),
            }
        } else {
            line.to_string()
        };
        io::print_bootlog_line(&format!("{styled}\r\n"), delay(1000));
    }
}

fn botnet() {
    let cluster_count = 11usize;
    let nodes: Vec<u64> = (0..cluster_count).map(|_| range(100, 200)).collect();
    let total: u64 = nodes.iter().sum();
    for i in 0..=total {
        if exited() { return; }
        ps(&format!("\rEstablishing connections: {i:4}/{total}"), 5);
    }
    pl("", 0);
    for (i, n) in nodes.iter().enumerate() {
        pl(&format!("  Cluster #{i:02} ({n} nodes)"), 50);
    }
    let mut online = vec![false; cluster_count];
    loop {
        if exited() { return; }
        for i in 0..cluster_count {
            if !online[i] && chance(12) { online[i] = true; }
        }
        for (i, n) in nodes.iter().enumerate() {
            let prefix = if i == 0 {
                format!("\x1b[{cluster_count}A\x1b[2K\x1b[0G")
            } else {
                "\x1b[2K\x1b[0G".to_string()
            };
            let status = if online[i] {
                "\x1b[1;32monline\x1b[0m"
            } else {
                "\x1b[1;33mbooting\x1b[0m"
            };
            pl(&format!("{prefix}  Cluster #{i:02} ({n} nodes) [{status}]"), 50);
        }
        if online.iter().all(|x| *x) { break; }
    }
    pl("+ Synchronizing clocks... [done]", 200);
    pl("+ Sending login information... [done]", 200);
    pl("+ Sending command... [done]", 200);
    pl(">> Botnet update complete.", 200);
}

fn bruteforce() {
    let hashes: Vec<String> = (0..9).map(|_| hex_string(64)).collect();
    pl("=> Hashes to decrypt", 100);
    for h in &hashes { pl(&format!("  {h}"), 100); }
    const COLORS: [u32; 30] = [203,209,208,178,178,184,148,154,119,119,83,84,48,43,44,44,38,33,69,63,99,99,129,128,164,163,163,198,204,203];
    const SPIN: [char; 4] = ['|', '/', '-', '\\'];
    for step in 0..=30usize {
        if exited() { return; }
        let mut bar = String::new();
        for (idx, code) in COLORS.iter().enumerate() {
            let ch = if idx < step { '=' } else if idx == step { SPIN[step % 4] } else { ' ' };
            bar.push_str(&format!("\x1b[38;5;{code}m{ch}\x1b[0m"));
        }
        ps(&format!("\r=> Extracting Rainbow Table [{bar}]"), 100);
    }
    pl("", 0);
    pl("=> Begin matching", 100);
    let cycles = range_usize(400, 800);
    for cycle in 0..cycles {
        if exited() { return; }
        let reveal = {
            let frac = cycle as f64 / cycles as f64;
            (frac * frac * 64.0) as usize
        };
        for (slot, target) in hashes.iter().enumerate() {
            let mut candidate = String::new();
            candidate.push_str(&target[..reveal.min(64)]);
            candidate.push_str(&hex_string(64 - reveal.min(64)));
            let green_len = reveal.saturating_add(range_usize(0, 2)).min(64);
            let (green, rest) = candidate.split_at(green_len.min(candidate.len()));
            let up = if slot == 0 && cycle > 0 { "\x1b[9A" } else { "" };
            pl(&format!("{up}\r :: \x1b[32m{green}\x1b[0m\x1b[31m{rest}\x1b[0m ::"), 5);
        }
    }
    pl("=> Match found", 100);
    for h in &hashes {
        pl(&format!("  {h}:\x1b[1m{}\x1b[0m", username()), 100);
    }
}

fn cargo_packages(count: usize) -> Vec<(String, String)> {
    let pool = data::lines(data::CRATE_NAMES);
    let names = shuffled(pool);
    (0..count)
        .map(|i| {
            let name = names[i % names.len()].to_string();
            (name, version())
        })
        .collect()
}

fn cargo() {
    let packages = cargo_packages(range_usize(25, 75));
    for (name, ver) in &packages {
        if exited() { return; }
        pl(&format!("\x1b[1;32m Downloading\x1b[0m {name} v{ver}"), delay(1500));
    }
    for (name, ver) in &packages {
        if exited() { return; }
        pl(&format!("\x1b[1;32m   Compiling\x1b[0m {name} v{ver}"), delay(1500));
    }
    let secs: f64 = rng().gen_range(0.0..1.0);
    pl(&format!("\x1b[1;32m    Finished\x1b[0m release [optimized] target(s) in {secs:.2} secs"), 0);
}

fn cc() {
    let paths = data::lines(data::KERNEL_PATHS);
    let crates = data::lines(data::CRATE_NAMES);
    let compiler = if chance(65) { "clang" } else { "gcc" };
    let opt = choose_str(&["-O0", "-O1", "-O2", "-O3", "-Os", "-Og", "-Ofast"]);
    let mut base = format!("{compiler} -c {opt} -Wall");
    let flag_pool = ["-Wno-parentheses", "-Wno-unknown-pragmas", "-Wno-unused-variable", "-Wno-unused-variable", "-Wno-sign-compare", "-Wextra", "-Wundef", "-funroll-loops", "-fsigned-char", "-Wno-unused-parameter", "-fPIC"];
    for _ in 0..range(0, 8) { base.push_str(&format!(" {}", choose_str(&flag_pool))); }
    // Include directories are the directories of source files.
    let mut dirs: Vec<&str> = paths.iter().map(|p| {
        match p.rfind('/') { Some(idx) => &p[..idx], None => *p }
    }).collect();
    dirs.dedup();
    for _ in 0..range(10, 30) { base.push_str(&format!(" -I{}", choose(&dirs))); }
    let def_pool = ["NDEBUG", "SHARED", "MODULE_NAME=lib", "DEBUG", "__KERNEL__", "MODULE"];
    for _ in 0..range(0, 6) { base.push_str(&format!(" -D{}", choose_str(&def_pool))); }

    let count = range_usize(150, 600);
    let mut objects: Vec<String> = Vec::new();
    let mut shuffled_paths = shuffled(paths.clone());
    for i in 0..count {
        let raw = shuffled_paths[i % shuffled_paths.len()];
        let obj = match raw.rfind('.') {
            Some(idx) => format!("{}.o", &raw[..idx]),
            None => format!("{raw}.o"),
        };
        objects.push(obj);
    }
    for obj in &objects {
        if exited() { return; }
        pl(&format!("{base} -o {obj}"), delay(150));
    }
    let libs: Vec<String> = (0..3).map(|_| format!("-l{}", choose(&crates))).collect();
    let program = choose(&crates);
    pl(&format!("{compiler} -o {program} {} {} ", objects.join(" "), libs.join(" ")), 0);
}

fn composer() {
    pl("\x1b[32mLoading composer repositories with package information\x1b[0m", 0);
    pl("\x1b[32mUpdating dependencies (including require-dev)\x1b[0m", 0);
    let pool = data::lines(data::COMPOSER_NAMES);
    let names = shuffled(pool);
    let count = range_usize(20, 70).min(names.len());
    for i in 0..count {
        if exited() { return; }
        let name = names[i];
        pl(&format!("  - Installing \x1b[32m{name}\x1b[0m (\x1b[33m{}\x1b[0m): Loading from cache", wide_version()), delay(1500));
    }
    pl("\x1b[32mWriting lock file\x1b[0m", 0);
    pl("\x1b[32mGenerating autoload files\x1b[0m", 0);
}

fn cryptomining() {
    let count = range_usize(600, 900);
    let mut accepted: u64 = 0;
    for _ in 0..count {
        if exited() { return; }
        if chance(1) {
            accepted += 1;
            let time = current_time_hms();
            pl(&format!("\x1b[1;36m  ℹ\x1b[0m  \x1b[35m{time}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mstratum      \x1b[0mReceived new job #{}  seed: #{}  target: #{}", hex_string(8), hex_string(32), hex_string(24)), 100);
        }
        if chance(1) { accepted += 1; }
        let g0: f64 = rng().gen_range(16.5..18.0);
        let g1: f64 = rng().gen_range(16.5..18.0);
        let total = g0 + g1;
        let time = current_time_hms();
        pl(&format!("\x1b[32m  m\x1b[0m  \x1b[35m{time}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mcryptominer  \x1b[0mSpeed \x1b[1;36m {total:.2}\x1b[0m Mh/s    gpu/0 \x1b[36m{g0:.2}\x1b[0m gpu/1 \x1b[36m{g1:.2}\x1b[0m   [A{accepted}+0:R0+0:F0] Time: 00:00"), delay(250));
    }
}

fn docker_build() {
    // Sending build context
    let target: f64 = rng().gen_range(100.0..300.0);
    let mut current: f64 = 0.0;
    loop {
        if exited() { return; }
        ps(&format!("\rSending build context to Docker daemon  {current:.2}MB"), 100);
        if current >= target { break; }
        current = (current + rng().gen_range(5.0..25.0)).min(target);
    }
    let steps = range_usize(30, 90);
    let commands: Vec<(&str, &str)> = vec![
        ("tail -f /var/log/nginx/access.log", "weblog"),
        ("cargo run", "cargo"),
        ("./cryptominer.sh --gpu all --provider stratum", "cryptomining"),
        ("rkhunter --check", "rkhunter"),
        ("./botnet.sh", "botnet"),
        ("ansible-playbook", "ansible"),
        ("composer install", "composer"),
        ("sudo make install", "kernel_compile"),
        ("gcc app.c", "cc"),
        ("memdump -k -v", "memdump"),
        ("uv sync", "uv"),
        ("mkinitcpio --generate /boot/initramfs-custom2.img --kernel 5.7.12-arch1-1", "mkinitcpio"),
        ("./bruteforce.sh ./hashes.txt", "bruteforce"),
        ("./start-sumcity.sh", "simcity"),
        ("wpt run -f --browser-version=\"1.0\" --processes=16", "wpt"),
        ("wget -i downloads.txt", "download"),
        ("bcdedit /set {current} bootlog Yes && shutdown /r", "bootlog"),
        ("julia --threads auto --project .", "julia"),
        ("terraform --check", "terraform"),
    ];
    for i in 1..=steps {
        if exited() { return; }
        let (cmd, module) = choose(&commands);
        pl(&format!("\rStep {i}/{steps} : RUN {cmd}"), 100);
        if chance(40) {
            pl(&format!(" ---> Using cache ---> {}", hex_string(12)), 100);
        } else {
            pl(&format!(" ---> Running in {}", hex_string(12)), 100);
            run(module);
            if exited() { return; }
            pl(&format!(" ---> {}", hex_string(12)), 100);
        }
    }
    let images = data::lines(data::DOCKER_IMAGES);
    let image = choose(&images);
    ps(&format!("Successfully built {}", hex_string(12)), 0);
    ps(&format!("Successfully tagged {image}"), 0);
}

fn docker_image_rm() {
