fn download() {
    let width = io::get_terminal_width();
    let pool = data::lines(data::DOWNLOAD_FILES);
    let crates = data::lines(data::CRATE_NAMES);
    let exts = data::lines(data::WEBLOG_EXTS);
    let file_count = range_usize(3, 8);
    let name_field = if width > 20 { (width - 20) / 3 } else { 10 };
    for _ in 0..file_count {
        if exited() { return; }
        let filename = if chance(70) {
            choose(&pool).to_string()
        } else {
            format!("{}.{}", choose(&crates), choose(&exts))
        };
        let speed_base: f64 = rng().gen_range(25.0..80.0);
        let mut percent: u32 = 0;
        loop {
            if exited() { return; }
            let bar_width = width.saturating_sub(name_field + 44).max(5);
            let bar = if percent == 0 {
                " ".repeat(bar_width)
            } else if percent >= 100 {
                "=".repeat(bar_width)
            } else {
                let filled = (bar_width * percent as usize / 100).max(1);
                format!("{}█{}", "=".repeat(filled - 1), " ".repeat(bar_width - filled))
            };
            let speed: f64 = (speed_base + rng().gen_range(-5.0..5.0)).max(1.0);
            let size = speed / 20.0;
            let eta = if percent == 0 { 0 } else if percent < 50 { range(0, 3) } else { range(0, 1) };
            let line = format!("\x1b[2K\x1b[0G{filename:<name_field$}{percent}%[{bar}] {size:.2}MiB    {speed:.2}MiB/s   eta {eta}s");
            if percent >= 100 {
                pl(&line, 100);
                break;
            } else {
                ps(&line, 100);
            }
            percent = percent.saturating_add(range(1, 5) as u32).min(100);
        }
    }
}

fn julia() {
    let logo = [
        "               \x1b[1;32m_\x1b[0m",
        "   \x1b[1;34m_\x1b[0m       _ \x1b[1;31m_\x1b[0m\x1b[1;32m(_)\x1b[0m\x1b[1;35m_\x1b[0m     |  Documentation: https://docs.julialang.org",
        "  \x1b[1;34m(_)\x1b[0m     | \x1b[1;31m(_)\x1b[0m \x1b[1;35m(_)\x1b[0m    |",
        "   _ _   _| |_  __ _   |  Type \"?\" for help, \"]?\" for Pkg help.",
        "  | | | | | | |/ _` |  |",
        "  | | |_| | | | (_| |  |  Version 1.7.3 (2022-05-06)",
        " _/ |\\__'_|_|_|\\__'_|  |  Fedora 35 build",
        "|__/                   |",
    ];
    for line in logo { println!("{line}\r"); }
    println!("\r");
    let pool = data::lines(data::JULIA_NAMES);
    let env_name = if chance(30) { "@v1.7".to_string() } else { choose(&pool).to_string() };
    pl(&format!("\x1b[1;32mjulia>\x1b[0m \x1b[2K\x1b[0G\x1b[1;34m({env_name}) pkg>\x1b[0m update"), 200);
    pl("\x1b[1;32m    Updating\x1b[0m registry at `~/.julia/registries/General.toml`", 100);
    pl("\x1b[1;32m   Resolving\x1b[0m package versions...", 100);
    let names = shuffled(pool.clone());
    let count = range_usize(8, 16).min(names.len());
    let packages: Vec<(String, String, String)> = (0..count)
        .map(|i| (names[i].to_string(), version(), version()))
        .collect();
    let special = range_usize(0, count - 1);
    for (i, (name, ver, _)) in packages.iter().enumerate() {
        if exited() { return; }
        let dashes = if name.len() < 22 { "─".repeat(22 - name.len()) } else { "─".to_string() };
        if i == special {
            pl(&format!("\x1b[1;32m  Installing\x1b[0m {name} {dashes} v{ver}"), delay(400));
            pl(&format!("\x1b[1A\x1b[2K\x1b[0G\x1b[1;32m   Installed\x1b[0m {name} {dashes} v{ver}"), delay(400));
        } else {
            pl(&format!("\x1b[1;32m   Installed\x1b[0m {name} {dashes} v{ver}"), delay(400));
        }
    }
    // Artifacts
    let artifacts: Vec<String> = {
        let mut v = Vec::new();
        let mut idx = range_usize(20, 40);
        for _ in 0..2 {
            v.push(names[idx % names.len()].to_string());
            idx += 7;
        }
        v
    };
    for artifact in &artifacts {
        if exited() { return; }
        pl(&format!("\x1b[1;32m Downloading\x1b[0m artifact: {artifact}"), 100);
        let mut percent: f64 = 0.0;
        let mut first = true;
        loop {
            let bar_width = 41usize;
            let filled = (bar_width as f64 * percent / 100.0) as usize;
            let bar = if percent >= 100.0 {
                format!("{}█", "=".repeat(bar_width - 1))
            } else if filled == 0 {
                " ".repeat(bar_width)
            } else {
                format!("{}█{}", "=".repeat(filled - 1), " ".repeat(bar_width - filled))
            };
            let prefix = if first { "" } else { "\x1b[1A\x1b[2K\x1b[0G" };
            pl(&format!("{prefix}\x1b[1;36m    Downloading\x1b[0m [{bar}] {percent:.2}%"), 50);
            first = false;
            if percent >= 100.0 { break; }
            percent = (percent + rng().gen_range(0.5..5.0)).min(100.0);
        }
        pl(&format!("\x1b[1A\x1b[2K\x1b[0G\x1b[1A\x1b[2K\x1b[0G\x1b[1;32m  Downloaded\x1b[0m artifact: {artifact}"), 100);
    }
    let (project_path, manifest_path) = if env_name == "@v1.7" {
        ("~/.julia/environments/v1.7/Project.toml".to_string(), "~/.julia/environments/v1.7/Manifest.toml".to_string())
    } else {
        (format!("~/Documents/code/julia/projects/{env_name}.jl/Project.toml"), format!("~/Documents/code/julia/projects/{env_name}.jl/Manifest.toml"))
    };
    pl(&format!("\x1b[1;32m    Updating\x1b[0m `{project_path}`"), 100);
    pl(&format!("\x1b[1;32m    Updating\x1b[0m `{manifest_path}`"), 100);
    for (name, ver, old) in &packages {
        let (symbol, code, text) = match range(0, 2) {
            0 => ("+", 10, format!("{name} v{ver}")),
            1 => ("↑", 11, format!("{name} v{old} ⇒ v{ver}")),
            _ => ("-", 9, format!("{name} v{ver}")),
        };
        pl(&format!("  \x1b[38;5;8m[{}]\x1b[0m \x1b[38;5;{code}m{symbol} {text}\x1b[0m", hex_string(8)), 100);
    }
    // Building artifacts
    let total_art = artifacts.len();
    pl(&format!("\x1b[1;36m  Progress\x1b[0m [{}] 0/{total_art}", " ".repeat(41)), 100);
    for (i, artifact) in artifacts.iter().enumerate() {
        let uuid = format!("{}-{}-{}-{}-{}", hex_string(8), hex_string(4), hex_string(4), hex_string(4), hex_string(12));
        let dashes = if artifact.len() < 16 { "─".repeat(16 - artifact.len()) } else { "─".to_string() };
        pl(&format!("\x1b[1A\x1b[2K\x1b[0G\x1b[1;32m    Building\x1b[0m {artifact} {dashes}→ `~/.julia/scratchspaces/{uuid}/{}/build.log`", hex_string(40)), 100);
        let filled = 41 * (i + 1) / total_art;
        let bar = format!("{}█{}", "=".repeat(filled.saturating_sub(1)), " ".repeat(41 - filled));
        pl(&format!("\x1b[1;36m  Progress\x1b[0m [{bar}] {}/{total_art}", i + 1), 100);
    }
    pl("\x1b[1A\x1b[2K\x1b[0G\x1b[1;32mPrecompiling\x1b[0m project...", 100);
    let total_pkg = packages.len();
    for step in 0..=total_pkg {
        let filled = if total_pkg == 0 { 41 } else { 41 * step / total_pkg };
        let bar = if step == total_pkg {
            "=".repeat(40) + "█"
        } else if filled == 0 {
            " ".repeat(41)
        } else {
            format!("{}█{}", "=".repeat(filled - 1), " ".repeat(41 - filled))
        };
        let prefix = if step == 0 { "" } else { "\x1b[1A\x1b[2K\x1b[0G" };
        pl(&format!("{prefix}\x1b[1;36m  Progress\x1b[0m [{bar}] {step}/{total_pkg}"), 50);
    }
    pl(&format!("\x1b[1A\x1b[2K\x1b[0G  {total_pkg} dependencies successfully precompiled in 0 seconds ({} already precompiled)", range(100, 400)), 100);
    pl("", 0);
    pl(&format!("\x1b[1;34m({env_name}) pkg>\x1b[0m \x1b[2K\x1b[0G\x1b[1;32mjulia>\x1b[0m "), 0);
}

fn kernel_compile() {
    let archs = ["alpha","arc","arm","arm64","avr32","blackfin","c6x","cris","frv","h8300","hexagon","ia64","m32r","m68k","microblaze","mips","mn10300","nios2","openrisc","parisc","powerpc","s390","score","sh","sparc","tile","um","unicore32","x86","xtensa"];
    let arch = choose_str(&archs);
    let pool = data::lines(data::KERNEL_PATHS);
    let count = range_usize(150, 500);
    for _ in 0..count {
        if exited() { return; }
        let raw = *choose(&pool);
        let path = transform_arch(raw, arch);
        let ext = match path.rfind('.') { Some(idx) => &path[idx + 1..], None => "" };
        let action = match ext {
            "o" => choose_str(&["CC","CC","CC","AR","AR","AS","HOSTCC"]),
            "h" => choose_str(&["WRAP","CHK","UPD","WRAP","CHK"]),
            "c" => "VDSO2C",
            "lds" => "LDS",
            "bin" => "OBJCOPY",
            _ => choose_str(&["CC","AR","CHK"]),
        };
        pl(&format!("  {action:<8}{path}"), delay(800));
    }
    pl(&format!("BUILD   arch/{arch}/boot/bzImage"), 100);
    pl("", 0);
    let setup = range(10000, 900000);
    let padded = setup + range(10000, 600000);
    pl(&format!("Setup is {setup} bytes (padded to {padded} bytes)."), 0);
    pl(&format!("System is {} kB", range(1000, 2600)), 0);
    pl(&format!("CRC {}", hex_string(8)), 0);
    pl(&format!("Kernel: arch/{arch}/boot/bzImage is ready (#1)"), 0);
    pl("", 0);
}

fn transform_arch(raw: &str, arch: &str) -> String {
    if let Some(rest) = raw.strip_prefix("arch/") {
        match rest.find('/') {
            Some(idx) => format!("arch/{arch}/{}", &rest[idx + 1..]),
            None => raw.to_string(),
        }
    } else {
        raw.to_string()
    }
}

fn memdump() {
    let mut addr: u64 = rng().gen::<u64>() & !15u64;
    let count = range_usize(80, 180);
    for _ in 0..count {
        if exited() { return; }
        let bytes = random_bytes(16);
        let hexpart = bytes.iter().map(|b| format!("{b:02x}")).collect::<Vec<_>>();
        let ascii: String = bytes.iter().map(|b| if (32..127).contains(b) { *b as char } else { '.' }).collect();
        pl(&format!("{addr:016x}  {}  {}  |{ascii}|", hexpart[..8].join(" "), hexpart[8..].join(" ")), delay(300));
        addr = addr.wrapping_add(16);
    }
}

fn mkinitcpio() {
    let versions = data::lines(data::MK_VERSIONS);
    let comps_pool = data::lines(data::MK_COMPS);
    let mut comps = comps_pool.clone();
    comps.extend(["xz", "lz4", "zstd", "cat"]);
    let version = *choose(&versions);
    let compression = *choose(&comps);
    let hook_order = ["base","udev","usr","autodetect","modconf","block","net","mdadm","mdadm_udev","keyboard","keymap","consolefont","encrypt","resume","fsck","filesystems"];
    let mut hooks: Vec<&str> = vec!["base", "udev"];
    for hook in hook_order.iter().skip(2).take(hook_order.len() - 4) {
        if chance(60) { hooks.push(hook); }
    }
    hooks.push("fsck");
    hooks.push("filesystems");
    for preset in ["default", "fallback"] {
        if exited() { return; }
        let suffix = if preset == "default" { "" } else { "-fallback" };
        pl(&format!("\x1b[1;32m==> \x1b[0m\x1b[1mBuilding image from preset: /etc/mkinitcpio.d/linux.preset: '{preset}'\x1b[0m"), 0);
        pl(&format!("\x1b[1;34m  -> \x1b[0m\x1b[1m-k /boot/vmlinuz-linux -c /etc/mkinitcpio.conf -g /boot/initramfs-linux{suffix}.img\x1b[0m"), 0);
        pl(&format!("\x1b[1;32m==> \x1b[0m\x1b[1mStarting build: {version}\x1b[0m"), 0);
        for hook in &hooks {
            if exited() { return; }
            pl(&format!("\x1b[1;34m  -> \x1b[0m\x1b[1mRunning build hook: [{hook}]\x1b[0m"), delay(800));
        }
        pl("\x1b[1;32m==> \x1b[0m\x1b[1mGenerating module dependencies\x1b[0m", 200);
        pl(&format!("\x1b[1;32m==> \x1b[0m\x1b[1mCreating {compression}-compressed initcpio image: /boot/initramfs-linux{suffix}.img\x1b[0m"), 300);
        pl("\x1b[1;32m==> \x1b[0m\x1b[1mImage generation successful\x1b[0m", 0);
    }
}

fn rkhunter() {
    // This module historically printed with println! rather than the shared
    // line printer, including the trailing carriage return in each string.
    let say = |line: &str| println!("{line}\r");
    say(&format!("Running Rootkit Hunter version {} on localhost", version()));
    say("");
    say(&format!("Info: Start date is {}", chrono::Utc::now().format("%a %d %b %Y %I:%M:%S %p UTC")));
    say("");
    say("Info: Detected operating system is 'Linux'");
    // The original forgot the newline after the O/S name, so the next
    // message is glued onto the same line.
    print!("Found O/S name: Ubuntu {}\r", version());
    println!("Info: Environment shell is /bin/bash; rkhunter is using dash\r");
    say("Info: Using configuration file '/etc/rkhunter.conf'");
    say("Info: Installation directory is '/usr'");
    say("Info: Using language 'en'");
    say("Info: Using '/var/lib/rkhunter/db' as the database directory");
    say("Info: Using '/usr/share/rkhunter/scripts' as the support script directory");
    say("Info: Using '/var/lib/rkhunter/db' as the database directory");
    say("Info: Using '/usr/share/rkhunter/scripts' as the support script directory");
    say("Info: Using '/usr/local/sbin /usr/local/bin /usr/sbin /usr/bin /sbin /bin /usr/games /usr/local/games /snap/bin /usr/libexec' as the command directories");
    say("Info: Using '/var/lib/rkhunter/tmp' as the temporary directory");
    say("Info: No mail-on-warning address configured");
    say("");
    say("Checking if the O/S has changed since last time...");
    say("Info: Nothing seems to have changed.");
    say("Info: Locking is not being used");
    say("");
    say("Starting system checks...");
    say("");
    io::sleep_scaled(200);
    let sections = ["malware checks", "check of possible rootkit files and directories", "filesystem checks", "checks on the network ports", "check for backdoor ports", "system boot checks", "system configuration file checks"];
    let section = choose_str(&sections);
    say(&format!("Performing {section}"));
    let pool = data::lines(data::RKHUNTER_ITEMS);
    let items = shuffled(pool);
    let rootkit_section = section == "check of possible rootkit files and directories";
    if rootkit_section {
        let rootkits = ["beX2", "Dica", "Marvin", "Sneakin", "Suspicion"];
        let rootkit = choose_str(&rootkits);
        say(&format!("  Checking for {rootkit} Rootkit..."));
        let count = range_usize(10, 20);
        let selected: Vec<&str> = items.iter().take(count).cloned().collect();
        let width = selected.iter().map(|s| s.len()).max().unwrap_or(40) + 6;
        for item in &selected {
            if exited() { return; }
            let status = rkhunter_status();
            say(&format!("    {:<width$}{}", item, status, width = width));
            io::sleep_scaled(delay(700));
        }
        say(&format!("  {:<width$}{}", format!("{rootkit} Rootkit"), rkhunter_status(), width = width));
        say("");
    } else {
        let count = range_usize(10, 25);
        let selected: Vec<&str> = items.iter().take(count).cloned().collect();
        let width = selected.iter().map(|s| s.len()).max().unwrap_or(40) + 6;
        for item in &selected {
            if exited() { return; }
            let status = rkhunter_status();
            say(&format!("  {:<width$}{}", item, status, width = width));
            io::sleep_scaled(delay(700));
        }
        say("");
    }
}

fn rkhunter_status() -> String {
    match range(0, 99) {
        0..=84 => "[ Not found\x1b[0m ]".to_string(),
        85..=94 => "[ \x1b[31mFound\x1b[0m ]".to_string(),
        _ => "[ Skipped\x1b[0m ]".to_string(),
    }
}

fn simcity() {
    let phrases = data::lines(data::SIMCITY_PHRASES);
    const SPIN: [char; 4] = ['/', '-', '\\', '|'];
    let mut first = true;
    loop {
        if exited() { return; }
        let phrase = *choose(&phrases);
        let spins = range_usize(30, 90);
        for i in 0..spins {
            if exited() { return; }
            let prefix = if first { "" } else { "\r" };
            first = false;
            ps(&format!("{prefix}[ ] {phrase}... {}", SPIN[i % 4]), 80);
        }
        pl(&format!("\r[o] \x1b[37m{phrase}... OK\x1b[0m"), 80);
        first = false;
    }
}

fn terraform() {
    let start = std::time::Instant::now();
    pl("Acquiring state lock. This may take a few moments...", 300);
    let types = data::lines(data::TERRAFORM_TYPES);
    let names = data::lines(data::TERRAFORM_NAMES);
    let count = range_usize(90, 270);
    for _ in 0..count {
        if exited() { return; }
        let ty = choose(&types);
        let name = choose(&names);
        let elapsed = start.elapsed().as_secs();
        let status = match range(0, 9) {
            0 => "Creating...".to_string(),
            1 => format!("Creation complete after {elapsed}s [id={name}]"),
            2 => format!("Destroying... [id={name}]"),
            3 => format!("Destruction complete after {elapsed}s"),
            4 => format!("Modifying... [id={name}]"),
            5 => format!("Modifications complete after {elapsed}s [id={name}]"),
            6 => format!("Still creating... [{elapsed}s elapsed]"),
            7 => format!("Still modifying... [id={name}, {elapsed}s elapsed]"),
            8 => format!("Still destroying... [id={name}, {elapsed}s elapsed]"),
            _ => format!("Refreshing state... [id={name}]"),
        };
        pl(&format!("\x1b[1m{ty}.{name}: {status}\x1b[0m"), delay(400));
    }
}

fn format_size(mib: f64) -> String {
    if mib < 1.0 {
        format!("{:.2} KiB", mib * 1024.0)
    } else {
        format!("{mib:.2} MiB")
    }
}

fn uv() {
    let minor = range(9, 13);
    pl(&format!("Using CPython 3.{}.{}", minor, range(0, 25)), 100);
    pl("Creating virtualenv at: .venv", 100);
    let pool = data::lines(data::CRATE_NAMES);
    let mut packages: Vec<(String, String)> = Vec::new();
    let mut names = shuffled(pool.clone());
    let count = range_usize(70, 170);
    for i in 0..count {
        let name = names[i % names.len()].to_string();
        packages.push((name, version()));
    }
    const SPINNERS: [&str; 10] = ["⠋","⠙","⠹","⠸","⠼","⠴","⠦","⠧","⠇","⠏"];
    for (i, (name, ver)) in packages.iter().enumerate() {
        if exited() { return; }
        ps(&format!("\x1b[2K\x1b[0G{} {name}=={ver}", SPINNERS[i % 10]), 10);
    }
    let resolved_ms: f64 = rng().gen_range(50.0..300.0);
    ps(&format!("\x1b[2K\x1b[0G\x1b[2mResolved {} packages in {resolved_ms:.2}ms\x1b[0m", packages.len()), 10);
    let prepared = range_usize(50, 100);
    for i in 1..=prepared {
        ps(&format!("\x1b[2K\x1b[0G\x1b[2m{} Preparing packages... ({i}/{prepared})\x1b[0m", SPINNERS[i % 10]), 10);
    }
    let prepared_ms: f64 = rng().gen_range(40.0..200.0);
    ps(&format!("\x1b[2K\x1b[0G\x1b[2mPrepared {prepared} packages in {prepared_ms:.2}ms\x1b[0m"), 10);
    pl("", 0);
    pl("", 0);
    // Download each package with a dash progress bar.
    for (name, _) in &packages {
        if exited() { return; }
        let total: f64 = rng().gen_range(0.5..20.0);
        let steps = range_usize(4, 15);
        for step in 1..=steps {
            let current = total * step as f64 / steps as f64;
            let filled = (30.0 * current / total) as usize;
            let bar = format!("{}{}", "-".repeat(filled), " ".repeat(30 - filled));
            let pair = format!("{}/{}", format_size(current), format_size(total));
            pl(&format!("\x1b[1A\x1b[2K\x1b[0G\x1b[2m{name}\x1b[0m{} \x1b[32m{bar}\x1b[0m{pair:>22}  ", " ".repeat(33usize.saturating_sub(name.len()))), 30);
        }
    }
    // Installing wheels
    for i in 0..=prepared {
        if exited() { return; }
        let filled = if prepared == 0 { 30 } else { 30 * i / prepared };
        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(30 - filled));
        ps(&format!("\x1b[2K\x1b[0G[{bar}] [{i}/{prepared}] Installing wheels..."), 10);
    }
    let secs: f64 = rng().gen_range(0.5..3.0);
    ps(&format!("\x1b[2K\x1b[0G\x1b[2mInstalled {prepared} packages in {secs:.2}s\x1b[0m"), 0);
    pl("", 0);
}

