    say("Info: Using '/usr/share/rkhunter/scripts' as the support script directory");
    say("Info: Using '/usr/local/sbin /usr/local/bin /usr/sbin /usr/bin /sbin /bin /usr/games /usr/local/games /snap/bin /usr/libexec' as the command directories");
    say("Info: Using '/var/lib/rkhunter/tmp' as the temporary directory");
