    say("Starting system checks...");
    say("");
    io::sleep_scaled(200);
    let sections = ["malware checks", "check of possible rootkit files and directories", "filesystem checks", "checks on the network ports", "check for backdoor ports", "system boot checks", "system configuration file checks"];
    let section = choose_str(&sections);
    say(&format!("Performing {section}"));
    let pool = data::lines(data::RKHUNTER_ITEMS);
    let items = shuffled(pool);
    let rootkit_section = section == "check of possible rootkit files and directories";
    if rootkit_section {
        let rootkits = ["beX2", "Dica", "Marvin", "Sneakin", "Suspicion"];
        let rootkit = choose_str(&rootkits);
        say(&format!("  Checking for {rootkit} Rootkit..."));
        let count = range_usize(10, 20);
        let selected: Vec<&str> = items.iter().take(count).cloned().collect();
        let width = selected.iter().map(|s| s.len()).max().unwrap_or(40) + 6;
        for item in &selected {
            if exited() { return; }
            let status = rkhunter_status();
            say(&format!("    {:<width$}{}", item, status, width = width));
            io::sleep_scaled(delay(700));
        }
        say(&format!("  {:<width$}{}", format!("{rootkit} Rootkit"), rkhunter_status(), width = width));
        say("");
    } else {
        let count = range_usize(10, 25);
        let selected: Vec<&str> = items.iter().take(count).cloned().collect();
        let width = selected.iter().map(|s| s.len()).max().unwrap_or(40) + 6;
        for item in &selected {
            if exited() { return; }
            let status = rkhunter_status();
            say(&format!("  {:<width$}{}", item, status, width = width));
            io::sleep_scaled(delay(700));
        }
        say("");
    }
}

