fn wpt() {
    let cats = data::lines(data::WPT_CATS);
    let total_tests = range(15000, 25000);
    let test_path = |cats: &Vec<&str>| -> String {
        format!("{}{}.html", choose(cats), range(1, 500))
    };
    pl(&format!("Running {total_tests} tests in web-platform-tests"), 100);
    pl(&format!("\x1b[A\x1b[K[0/{total_tests}] No tests running."), 50);
    let mut done: u64 = 0;
    while done < total_tests {
        if exited() { return; }
        // Occasional result blocks
        if chance(35) {
            let file = test_path(&cats);
            let base = file.rsplit('/').next().unwrap_or("test").trim_end_matches(".html");
            if chance(40) {
                pl(&format!("\x1b[A\x1b[K    ▶ Timed out in {file}"), 20);
                let expected = choose_str(&["PASS", "FAIL"]);
                let kind = choose_str(&["TIMEOUT", "FAIL", "PASS"]);
                pl(&format!("    │ ERROR [expected {expected}] {kind} test_{base} assert_"), 20);
            } else {
                pl(&format!("\x1b[A\x1b[K    ▶ Unexpected subtest result in {file}:"), 20);
                let expected = choose_str(&["PASS", "FAIL"]);
                let kind = choose_str(&["FAIL", "PASS", "TIMEOUT"]);
                let msg = match range(0, 3) {
                    0 => format!("assert_equals: expected {} but got {}", range(0, 500), range(0, 500)),
                    1 => "assert_throws_dom: function \"() => test()\" threw object \"TypeError: undefined is not a function\" that is not a DOMException".to_string(),
                    2 => "assert_true: expected true".to_string(),
                    _ => "assert_".to_string(),
                };
                pl(&format!("    │ ERROR [expected {expected}] {kind} test_{base} {msg}"), 20);
                let stack = range_usize(2, 6);
                for s in 0..stack {
