fn install_signal_handler() {
    use std::sync::atomic::{AtomicI32, Ordering};
    static PIPE_WRITE: AtomicI32 = AtomicI32::new(-1);
    extern "C" fn handler(_sig: libc::c_int) {
        let fd = PIPE_WRITE.load(Ordering::Relaxed);
        if fd >= 0 {
            let byte = [1u8];
            unsafe {
                libc::write(fd, byte.as_ptr() as *const libc::c_void, 1);
            }
        }
    }
    let mut fds = [0 as libc::c_int; 2];
    unsafe {
        if libc::pipe(fds.as_mut_ptr()) != 0 {
            return;
        }
        PIPE_WRITE.store(fds[1], Ordering::Relaxed);
        let read_fd = fds[0];
        let builder = std::thread::Builder::new().name("ctrl-c".to_string());
        let _ = builder.spawn(move || {
            let mut buf = [0u8; 1];
            loop {
                let read = libc::read(read_fd, buf.as_mut_ptr() as *mut libc::c_void, 1);
                if read > 0 {
                    break;
                } else if read == 0 {
                    std::thread::sleep(Duration::from_millis(10));
                }
            }
            println!("Saving work to disk...");
            let _ = io::stdout().flush();
            std::process::exit(0);
        });
        for signal in [libc::SIGINT, libc::SIGTERM, libc::SIGHUP] {
            let mut action: libc::sigaction = std::mem::zeroed();
            action.sa_sigaction = handler as usize;
            libc::sigemptyset(&mut action.sa_mask);
            libc::sigaction(signal, &action, std::ptr::null_mut());
        }
    }
}

fn try_inhibit() -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::net::UnixStream;
        let path = "/var/run/dbus/system_bus_socket";
        match UnixStream::connect(path) {
            Ok(stream) => {
                // Keeping the stream open would keep a system connection
                // alive; the fake workload does not need anything further.
                std::mem::forget(stream);
                Ok(())
            }
            Err(err) => {
                let code = err.raw_os_error().unwrap_or(0);
                Err(format!("system: I/O error: {} (os error {})", io::Error::from_raw_os_error(code), code))
            }
        }
    }
    #[cfg(not(unix))]
    {
        Ok(())
    }
}

fn main() -> io::Result<()> {
    let matches = build_command().get_matches();

    if let Some(shell_name) = matches.get_one::<String>("print-completions") {
        let shell = match shell_name.as_str() {
            "bash" => clap_complete::Shell::Bash,
            "elvish" => clap_complete::Shell::Elvish,
            "fish" => clap_complete::Shell::Fish,
            "powershell" => clap_complete::Shell::PowerShell,
            _ => clap_complete::Shell::Zsh,
        };
        clap_complete::generate(shell, &mut build_command(), "genact", &mut io::stdout());
        return Ok(());
    }

    if matches.get_flag("print-manpage") {
        let man = clap_mangen::Man::new(build_command());
        man.render(&mut io::stdout())?;
        return Ok(());
    }

    if matches.get_flag("list-modules") {
        println!("Available modules:");
        for module in MODULES {
            println!("  {module}");
        }
        return Ok(());
    }

    let selected: Vec<String> = match matches.get_many::<String>("modules") {
        Some(values) => values.cloned().collect(),
        None => MODULES.iter().map(|module| module.to_string()).collect(),
    };
    let speed_factor = *matches.get_one::<f64>("speed-factor").unwrap_or(&1.0);
    let instant_print_lines = *matches.get_one::<u32>("instant-print-lines").unwrap_or(&0);
    let exit_after_time = matches.get_one::<Duration>("exit-after-time").cloned();
    let exit_after_modules = matches.get_one::<u32>("exit-after-modules").cloned();

    io::init(speed_factor, instant_print_lines, exit_after_time);
    install_signal_handler();

    if matches.get_flag("inhibit") {
        if let Err(error) = try_inhibit() {
            println!("WARN: failed to set up idle inhibition: {error}");
        }
    }

    use rand::seq::SliceRandom;
    let mut completed: u32 = 0;
    loop {
        if io::exit_requested() {
            break;
        }
        let module = selected.choose(&mut rand::thread_rng()).map(|s| s.as_str()).unwrap_or("cargo");
        modules::run(module);
        completed += 1;
        if let Some(limit) = exit_after_modules {
            if completed >= limit {
                break;
            }
        }
        if io::exit_requested() {
            break;
        }
    }
    println!("Saving work to disk...");
    Ok(())
}
