fn parse_duration(s: &str) -> Result<Duration, String> {
    // A duration such as "2h10min", "1.5s" or "500ms", made up of one or
    // more number+unit components.
    if s.trim().is_empty() {
        return Err("value was empty".to_string());
    }
    let bytes = s.as_bytes();
    let mut pos = 0usize;
    let mut total_nanos: u128 = 0;
    while pos < bytes.len() {
        while pos < bytes.len() && bytes[pos] == b' ' {
            pos += 1;
        }
        if pos >= bytes.len() {
            break;
        }
        if !bytes[pos].is_ascii_digit() {
            return Err(format!("expected number at {pos}"));
        }
        let num_start = pos;
        while pos < bytes.len() && bytes[pos].is_ascii_digit() {
            pos += 1;
        }
        let int_part = &s[num_start..pos];
        if int_part.len() > 18 {
            return Err("number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string());
        }
        let mut number: f64 = int_part.parse().unwrap_or(0.0);
        if pos < bytes.len() && bytes[pos] == b'.' {
            let dot_pos = pos;
            pos += 1;
            let frac_start = pos;
            while pos < bytes.len() && bytes[pos].is_ascii_digit() {
                pos += 1;
            }
            if frac_start == pos {
                return Err(format!("invalid character at {dot_pos}"));
            }
            let frac = &s[frac_start..pos];
            number += format!("0.{frac}").parse::<f64>().unwrap_or(0.0);
            if pos < bytes.len() && bytes[pos] == b'.' {
                return Err(format!("invalid character at {pos}"));
            }
        }
        while pos < bytes.len() && bytes[pos] == b' ' {
            pos += 1;
        }
        if pos >= bytes.len() {
            return Err(format!("time unit needed, for example {int_part}sec or {int_part}ms"));
        }
        if bytes[pos] == b'.' {
            return Err(format!("invalid character at {pos}"));
        }
        let unit_start = pos;
        while pos < bytes.len() && (bytes[pos].is_ascii_alphabetic() || bytes[pos] >= 0x80) {
            pos += 1;
        }
        let unit = &s[unit_start..pos];
        if unit.is_empty() {
            return Err(format!("time unit needed, for example {int_part}sec or {int_part}ms"));
        }
        let multiplier_nanos: u128 = match unit {
            "ns" | "nsec" | "nsecs" | "nanosecond" | "nanoseconds" => 1,
            "us" | "usec" | "usecs" | "microsecond" | "microseconds" | "µs" | "μs" => 1_000,
            "ms" | "msec" | "msecs" | "millisecond" | "milliseconds" => 1_000_000,
            "s" | "sec" | "secs" | "second" | "seconds" => 1_000_000_000,
            "m" | "min" | "mins" | "minute" | "minutes" => 60_000_000_000,
            "h" | "hr" | "hrs" | "hour" | "hours" => 3_600_000_000_000,
            "d" | "day" | "days" => 86_400_000_000_000,
            "w" | "week" | "weeks" => 604_800_000_000_000,
            "M" | "month" | "months" => 2_630_016_000_000_000,
            "y" | "year" | "years" => 31_557_600_000_000_000,
            _ => {
                return Err(format!(
                    "unknown time unit \"{unit}\", supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)"
                ))
            }
        };
        let contribution = number * multiplier_nanos as f64;
        if !contribution.is_finite() || contribution > u64::MAX as f64 * 1_000_000_000.0 {
            return Err("number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string());
        }
        total_nanos += contribution as u128;
    }
    if total_nanos == 0 && !s.trim().chars().any(|c| c.is_ascii_digit()) {
        return Err("value was empty".to_string());
    }
    let secs = (total_nanos / 1_000_000_000) as u64;
    let nanos = (total_nanos % 1_000_000_000) as u32;
    Ok(Duration::new(secs, nanos))
}

fn build_command() -> Command {
