import subprocess, time, select, os, signal
def timed(exe, args, dur=3):
    p=subprocess.Popen([exe]+args, stdout=subprocess.PIPE)
    start=time.time(); buf=b""; times=[]
    while time.time()-start<dur:
        r,_,_=select.select([p.stdout],[],[],0.05)
        if r:
            chunk=os.read(p.stdout.fileno(), 4096)
            if not chunk: break
            buf+=chunk
            while b"\n" in buf:
                line,buf=buf.split(b"\n",1); times.append(round(time.time()-start,3))
        if p.poll() is not None: break
    p.kill(); return times
for exe in ["./executable","/tmp/newbin/executable"]:
    print(exe, "i5", timed(exe, ["-m","cargo","-i","5"], 3))
    print(exe, "i0", timed(exe, ["-m","cargo"], 3))
PY"}

