import subprocess, time, select, os
def measure(exe,mod,speed,dur=3):
    p=subprocess.Popen([exe,"-m",mod,"-s",str(speed)], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    start=time.time(); total=0; lines=0
    while time.time()-start<dur:
        r,_,_=select.select([p.stdout],[],[],0.05)
        if r:
            chunk=os.read(p.stdout.fileno(), 65536)
            if not chunk: break
            total+=len(chunk); lines+=chunk.count(b"\n")
